def gen(rng):
    def fmt(words, W):
        return '%d %d\n%s' % (len(words), W, ' '.join(words))

    def word(k):
        return ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(k))

    tests = [fmt(['a'], 1), fmt(['abc'], 3), fmt(['abc'], 10), fmt(['a', 'b', 'c'], 1), fmt(['a', 'b', 'c'], 5),
             fmt('code is poetry when it runs'.split(), 12), fmt(['a', 'bb', 'ccccc'], 5), fmt(['ab', 'cd', 'ef'], 8), fmt(['ab', 'cd'], 5),
             fmt(['xyz'] * 6, 7)]
    for _ in range(35):
        W = rng.randint(1, 14)
        n = rng.randint(1, 12)
        words = [word(rng.randint(1, W)) for _ in range(n)]
        tests.append(fmt(words, W))
    n = 100000
    tests.append(fmt([word(rng.randint(1, 5)) for _ in range(n)], 30))
    tests.append(fmt([word(1) for _ in range(n)], 1))
    tests.append(fmt([word(rng.randint(1, 100)) for _ in range(5000)], 100))
    tests.append(fmt([word(rng.randint(1, 4)) for _ in range(n)], 100))
    tests.append(fmt([word(100) for _ in range(5000)], 100))
    return tests

